sys_script_include.script:
gs.include("IllumioConstants");
var IllumioUtils = Class.create();
IllumioUtils.prototype = {
    /**
     * @param {String} [jobSysId] sys_id of the scheduled job this instance is working for. Only
     *                 used to correlate log lines. Most of the 25 construction sites have no job
     *                 -- Business Rules, UI Actions, AJAX -- and those lines are prefixed [-].
     *                 Methods that take a jobSysId of their own re-point the logger themselves.
     */
    initialize: function(jobSysId) {
        this.logger = new IllumioLogger(jobSysId, 'IllumioUtils');
    },

    VALID_IP_REGEX: /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,

    /**
     * Updates the job with given job content
     * @param {String} jobId System id of the scheduled job
     * @param {JSON} jobContent Object to add in the job record
     */
    /**
     * A progress sink that writes to a scheduled job's log.
     *
     * IllumioSyncFilterUtils takes an `onProgress(message)` and does not know what a scheduled
     * job is -- it is called from UI Actions that have none. This is the adapter, in one place
     * because sync, deletion and every preview want the same behaviour: append the line to the
     * job log, and do nothing at all when there is no job.
     *
     * Each call is a read and a write of the job record. That is affordable because the lines
     * are per filter and per term, not per row -- anything per row would have to buffer instead.
     *
     * @param {String} jobSysId sys_id of the scheduled job, nil for a sink that discards
     * @returns {Function} Callback for onProgress
     */
    jobProgressLogger: function(jobSysId) {
        var self = this;

        if (gs.nil(jobSysId)) {
            return function() {};
        }

        return function(message) {
            self.updateJobRecord(jobSysId, { logs: message });
        };
    },

    /**
     * Same signature as jobProgressLogger, syslog only.
     *
     * For commentary that is emitted once per BATCH or per WINDOW. Those lines scale with the
     * size of the run -- a 100k sync writes one per payload row, one per discovery window -- and
     * on the job record that is a read-append-write of the whole `logs` field for each of them,
     * against a field with a finite max_length. They belong in the correlated trail, where they
     * cost one insert each and can be pulled back with
     *
     *     message STARTSWITH "[<job sys_id>]"
     *
     * Deliberately NOT nil-guarded into a no-op the way jobProgressLogger is: a line with no job
     * id still belongs in syslog, it just carries the `[-]` prefix. The guard exists there
     * because updateJobRecord with no sys_id has nothing to write to.
     *
     * The job record keeps the counts that bound these lines -- "Payload Batches: N",
     * "Processing N records in M batches", "Total records found: N" -- and the phase-end
     * summaries. Per-batch detail is reachable from those, not absent.
     *
     * @param {String} jobSysId sys_id of the scheduled job; nil degrades the prefix, not the line
     * @returns {Function} function(message)
     */
    jobTraceLogger: function(jobSysId) {
        var self = this;

        return function(message) {
            self.logger.setContext(jobSysId).info(String(message));
        };
    },

    updateJobRecord: function(jobId, jobContent) {
        var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);

        if (jobGr.get(jobId)) {

            if (jobGr.job_status == "cancelled") return;

            // Update only if job is not invalidated
            if (jobGr.job_status != 'failed') {
                for (var key in jobContent) {
                    if (jobContent.hasOwnProperty(key)) {
                        if (key != "logs") {
                            jobGr[key] = jobContent[key];
                        } else {
                            // W1: no per-line timestamp. The same line is emitted to
                            // syslog_app_scope, which timestamps it there, and the job log is a
                            // milestone list rather than a trace.
                            var existing = jobGr.getValue('logs') || '';
                            jobGr.logs = existing + (existing ? '\n' : '') + jobContent[key];

                            // W2: the job log and Application Logs carry the same milestones.
                            // Anything worth a line on the job record is worth one in the
                            // correlated trail, where it sits in order next to the detail that
                            // produced it -- and where it is still readable after the job record
                            // has been trimmed or the run cancelled. This is the funnel, so every
                            // caller of updateJobRecord gets it without changing.
                            //
                            // Context is set from the jobId argument rather than left at whatever
                            // this instance was constructed with: one IllumioUtils is reused
                            // across jobs in the discovery and sync paths, and a milestone filed
                            // under the wrong job is worse than one filed under none.
                            this.logger.setContext(jobId).info(String(jobContent[key]));
                        }
                    }
                }
                jobGr.update();
            } else {
                this.logger.info('[_updateJobRecord] Given job is invalidated. Aborting further actions');
            }
        } else {
            this.logger.error('[_updateJobRecord] Scheduled job record for given sys_id (' + jobId + ') does not exist.');
        }
    },

    /**
     * Close out a cancelled job with a final log line saying where the run stopped.
     *
     * updateJobRecord above returns the moment a job is cancelled, so every ordinary log
     * write is dropped from then on -- which is why a cancelled run that is still unwinding
     * looks frozen rather than cancelled. This is the one deliberate bypass of that guard,
     * and it exists only to write that last line. Do not route ordinary logging through it.
     * @param {String} jobId System id of the scheduled job
     * @param {String} message Final log line, also shown as the current operation
     */
    finalizeCancelledJob: function(jobId, message) {
        var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);

        if (!jobGr.get(jobId)) {
            this.logger.error('[finalizeCancelledJob] Scheduled job record for given sys_id (' + jobId + ') does not exist.');
            return;
        }

        // W1: no per-line timestamp -- see updateJobRecord above. job_completed below is the
        // timestamp that matters on this particular line.
        var existingLogs = jobGr.getValue('logs') || '';
        jobGr.logs = existingLogs + (existingLogs ? '\n' : '') + message;
        jobGr.current_operation = message;
        jobGr.job_completed = new GlideDateTime();
        jobGr.update();

        // W2: both sinks, same as updateJobRecord. This one especially -- it is the last line a
        // cancelled run writes anywhere, and it is the line someone asking "where did it stop"
        // goes looking for.
        this.logger.setContext(jobId).info(String(message));
    },

    /**
     * Get critical label group name for given configuration
     * @param {String} configSysId SysId of PCE Configuration
     * @returns value of the critical label group
     **/
    getCritical: function(configSysId) {
        var criticalGroupConfig = {};
        var criticalConfigGr = new GlideRecordSecure(TABLE_CRITICAL_LABEL_GROUP_CONFIG);
        criticalConfigGr.addQuery('illumio_pce_configuration', configSysId);
        criticalConfigGr.query();
        while (criticalConfigGr.next()) {
            criticalGroupConfig[criticalConfigGr.illumio_label_dimension.key] = {
                groupName: criticalConfigGr.getValue('label_group'),
                visited: false,
            };
        }

        return criticalGroupConfig;
    },

    /**
     * Parse label information in the label group table
     * @param {Object} criticalGroupConfig JSON containing critical label group configuration
     * @param {Object} response Label Group details from PCE
     * @param {GlideRecord} pceConfig GlideRecord of PCE Configuration
     * @returns 
     */
    parseLabelsInResponse: function(criticalGroupConfig, response, pceConfig) {
        var labelGroupGr;
        var counter = 0;
        for (var index = 0; index < response.length; index++) {
            if (
                criticalGroupConfig[response[index].key] &&
                criticalGroupConfig[response[index].key]["groupName"] ==
                response[index].name
            ) {
                criticalGroupConfig[response[index].key]['visited'] = true;
                counter++;
            }
        }
        for (var type in criticalGroupConfig) {
            if (!criticalGroupConfig[type]['visited']) {
                this.logger.info('The Critical Label Group ({0}) for the Configuration named {1} does not match any label groups at PCE', [criticalGroupConfig[type]['groupName'], pceConfig.getDisplayValue()]);
            }
        }
        //If any invalid Critical Group Configuration is found, we will terminate the process
        if (counter != Object.keys(criticalGroupConfig).length) {
            throw new Error("[parseLabelsInResponse]Invalid Critical Group Configuration(s) Found");
        }


        for (var resIndex = 0; resIndex < response.length; resIndex++) {
            if (
                criticalGroupConfig[response[resIndex].key] &&
                criticalGroupConfig[response[resIndex].key]["groupName"] ==
                response[resIndex].name
            ) {
                criticalGroupConfig[response[resIndex].key]['visited'] = true;
                for (var labelIndex = 0; labelIndex < response[resIndex].labels.length; labelIndex++) {
                    labelGroupGr = new GlideRecordSecure(TABLE_PCE_LABEL_GROUP_DETAILS);
                    labelGroupGr.label_group_name = response[resIndex].name;
                    labelGroupGr.label_group_path = response[resIndex].href;
                    labelGroupGr.label_group_type = response[resIndex].key;
                    labelGroupGr.label_name = response[resIndex].labels[labelIndex].value;
                    labelGroupGr.label_path = response[resIndex].labels[labelIndex].href;
                    labelGroupGr.illumio_pce_configuration = pceConfig.getUniqueValue();
                    if (!labelGroupGr.insert()) {
                        this.logger.error(
                            '[parseLabelsInResponse] Error while inserting the record'
                        );
                    }
                }
            }
        }

    },


    /**
     * Fetch the details of label group from PCE
     * @param {GlideRecord} pceConfig GlideRecord of PCE Configuration
     * @returns {Boolean} true if the request was successfull else false
     */
    fetchLabelGroupsAndLabelsFromPCE: function(pceConfig) {
        try {
            var lgDetailsGr = new GlideRecordSecure(TABLE_PCE_LABEL_GROUP_DETAILS);
            lgDetailsGr.addQuery('illumio_pce_configuration', pceConfig.getUniqueValue());
            lgDetailsGr.query();
            lgDetailsGr.deleteMultiple();

            var criticalGroupConfig = this.getCritical(pceConfig.getUniqueValue());

            if (!gs.nil(criticalGroupConfig)) {
                if (!(pceConfig.mid_server.status == MID_SERVER_UP_STATUS && pceConfig.mid_server.validated == 'true')) {
                    this.logger.error("The configured MID Server with configuration record " + pceConfig.getValue("name") + " is down.");
                    return false;
                }

                var inputs = {};
                inputs['pce_configuration'] = pceConfig; // GlideRecord of table: x_illu2_illumio_illumio_pce_conf
                inputs['query_parameters'] = "";

                var actionTimeout = gs.getProperty('x_illu2_illumio.flow_action_timeout') || 30000;
                var result = sn_fd.FlowAPI.getRunner().action('x_illu2_illumio.fetch_label_groups').inForeground().withInputs(inputs).timeout(actionTimeout).run();
                var outputs = result.getOutputs();

                var statusCode = outputs['status'];
                var headers = outputs['headers'];
                var response = outputs['response'];

                if (statusCode == 200 || statusCode == 201) {
                    response = JSON.parse(response);

                    this.parseLabelsInResponse(
                        criticalGroupConfig,
                        response,
                        pceConfig
                    );
                    return true;
                }
                return false;
            }
            return true;
        } catch (ex) {
            this.logger.error('Exception while fetching data from PCE. ', ex);
            return false;
        }
    },

    /**
     * The critical label values of a PCE Configuration, by dimension.
     *
     * getCritical says which label group is critical for each dimension; this expands each of
     * those groups into the label values it contains. A workload whose label value for a
     * dimension appears in this list is skipped by the sync -- see hasCriticalLabelConflict.
     *
     * @param {String} pceConfigSysId sys_id of the PCE Configuration
     * @returns {Object} { dimensionKey: [labelValue, ...] }
     */
    getCriticalLabelsForPceConfig: function(pceConfigSysId) {
        var criticalGroupConfig = this.getCritical(pceConfigSysId);
        var dataObj = {};
        if (!gs.nil(criticalGroupConfig)) {
            for (var type in criticalGroupConfig) {
                dataObj[type] = [];
                var labelGroupGr = new GlideRecordSecure(TABLE_PCE_LABEL_GROUP_DETAILS);
                labelGroupGr.addQuery('illumio_pce_configuration', pceConfigSysId);
                labelGroupGr.addQuery('label_group_name', criticalGroupConfig[type]['groupName']);
                labelGroupGr.addQuery('label_group_type', type);
                labelGroupGr.query();
                while (labelGroupGr.next()) {
                    dataObj[type].push(labelGroupGr.getValue("label_name"));
                }
            }
        }
        return dataObj;
    },

    /**
     * Skip the workload with given sys id as it has critical labels
     * @param {Array} rec Array of records
     * @param {String} sys_id System id of the workload
     * @returns Modified array
     */
    removeRec: function(rec, sys_id) {
        var ax;
        while ((ax = rec.indexOf(sys_id + "")) !== -1) {
            this.logger.info("Skipped workload as label is critical (sys_id: " + sys_id + ")");
            rec.splice(ax, 1);
        }
        return rec;
    },

    /**
     * Get the count of label groups
     * @param {Object} configSysIds List of config sys Ids
     * @returns {object} Count object with number of label groups for each configuration
     */
    countLabelGroups: function(configSysIds) {
        var countObject = {};
        try {

            for (var configIndex in configSysIds) {
                var countGa = new GlideAggregate(TABLE_PCE_LABEL_GROUP_DETAILS);
                countGa.addQuery("illumio_pce_configuration", configSysIds[configIndex]);
                countGa.groupBy("label_group_name");
				countGa.addAggregate('COUNT');
                countGa.query();
                var count = 0;
				while (countGa.next()) {
					count++;
				}
				countObject[configSysIds[configIndex]] = count;
            }
        } catch (err) {
            this.logger.error("Error while fetching the count of labels", err);
        } finally {
            return countObject;
        }
    },

    /**
     * Modify the Array after removing workloads
     * @param {Array} arrRecords Array of workloads
     * @returns Modified array after removing workloads that should be skipped
     */
    skipRecordsForSync: function(selectedRecordsObject) {
        try {
            var arrRecords, flag = false,
                retRec = [],
                retObject = {},
                totalRecords = 0;

            // for each configuration fetch critical label data
            for (var configSysId in selectedRecordsObject) {
                var labelData = this.getCriticalLabelsForPceConfig(configSysId);
                arrRecords = selectedRecordsObject[configSysId];
                retRec = [];

                // for each workload check if it contains critical label
                for (var arrIndex = 0; arrIndex < arrRecords.length; arrIndex++) {
                    flag = false;

                    // loop through all label dimensions
                    for (var type in labelData) {

                        if (gs.nil(labelData[type]) || labelData[type].length == 0)
                            continue;

                        var fieldValueGr = new GlideRecordSecure(TABLE_PCE_WORKLOAD_FIELD_VALUE);
                        fieldValueGr.addQuery('illumio_pce_workload', arrRecords[arrIndex]);
                        fieldValueGr.addQuery('illumio_label_dimension.key', type);
                        fieldValueGr.addQuery(
                            'pce_value',
                            'IN',
                            labelData[type]
                        );
                        fieldValueGr.query();

                        while (fieldValueGr.next()) {
                            if (fieldValueGr.getValue("cmdb_value") != fieldValueGr.getValue("pce_value")) {
                                flag = true;
                                break;
                            }
                        }

                        if (flag)
                            break;
                    }

                    if (!flag) {
                        retRec.push(arrRecords[arrIndex] + '');
                        totalRecords += 1;
                    } else {
                        this.logger.info('Skipped workload as label is critical (sys_id: {0})', arrRecords[arrIndex]);
                    }

                }
                retObject[configSysId] = retRec;
            }
        } catch (exc) {
            this.logger.error('Exception occurred while checking critical records', exc);
        } finally {
            return {
                filteredRecords: retObject,
                totalRecords: totalRecords
            };
        }
    },

    /**
     * Get the total number of records
     * @param {String} tableName Name of the table
     * @param {String} configuration SysID
     * @returns Count of rows in the table
     */
    getTotalRecords: function(tableName, configSysId) {
        try {

            var count = new GlideAggregate(tableName);
            count.addQuery("illumio_pce_configuration", configSysId);
            count.addAggregate('count');
            count.query();
            var result = 0;
            if (count.next())
                result = count.getAggregate('COUNT');
            return result;

        } catch (ex) {
            this.logger.error("Exception occurred while getting total number of records", ex);
        }
    },


    /**
     * Get the interfaces object that can be synced
     * @param {String} workloadSysId System id of the workload
     * @param {JSON} mappedFields object of Mapping fields
     * @returns {JSON} object with the details of interfaces to sync
     */
    getInterfacesObject: function(workloadGr) {

        var visitedIps = {},
            interfaces = [],
            state = {},
            key, cmdbKey, cmdbValue, publicIP;
        try {
            var interfaceObject = JSON.parse(workloadGr.getValue("interfaces"));
            var hostname = workloadGr.getValue("hostname");

            // get state of mapped cmdb ip addresses
            for (var index = 0; index <= MAX_IP_ADDRESSES; index++) {
                key = "umw" + index;
                if (!gs.nil(interfaceObject[key]))
                    state[key] = this.getState(interfaceObject[key]["cmdb_value"]);
            }

            // set umw0 as public ip address
            if (this.canSyncIP("umw0", state["umw0"], hostname)) {

                interfaces.push({
                    name: "umw0",
                    address: interfaceObject["umw0"]["cmdb_value"]
                });

                publicIP = interfaceObject["umw0"]["cmdb_value"];
                visitedIps[interfaceObject["umw0"]["cmdb_value"]] = true;

            }


            // set pce umw1 to umw32 ip addresses

            var cmdbIndex = 1;
            for (var ipindex = 1; ipindex < MAX_IP_ADDRESSES; ipindex++) {

                key = "umw" + ipindex;

                // set pce value
                if (!gs.nil(interfaceObject[key])) {
                    var pceValue = interfaceObject[key]["pce_value"];
                    if (!gs.nil(pceValue)) {
                        visitedIps[pceValue] = true;
                        interfaces.push({
                            name: key,
                            address: pceValue
                        });
                        continue;
                    }
                }

                // set valid cmdb value
                while (cmdbIndex < MAX_IP_ADDRESSES) {
                    cmdbKey = "umw" + cmdbIndex
                    if (gs.nil(interfaceObject[cmdbKey])) {
                        cmdbIndex++;
                        continue;
                    }

                    cmdbValue = interfaceObject[cmdbKey]["cmdb_value"];
                    if (this.canSyncIP(cmdbKey, state[cmdbKey], hostname) && !visitedIps[cmdbValue]) {
                        interfaces.push({
                            name: key,
                            address: cmdbValue
                        });
                        visitedIps[cmdbValue] = true;
                        cmdbIndex++;
                        break;
                    }
                    cmdbIndex++;
                }
            }

            // check for more IP addresses in the cmdb if exist then add logs
            while (cmdbIndex < MAX_IP_ADDRESSES) {
                cmdbKey = "umw" + cmdbIndex;

                if (gs.nil(interfaceObject[cmdbKey]))
                    break;

                cmdbValue = interfaceObject[cmdbKey]["cmdb_value"];
                if (gs.nil(visitedIps[cmdbValue]) && this.canSyncIP(cmdbKey, state[cmdbKey], hostname))
                    this.logger.info("Skipping IP address {0} for workload with hostname {1} as there are already {2} IP addresses in the PCE", [cmdbKey, hostname, MAX_IP_ADDRESSES]);

                cmdbIndex++;
            }
        } catch (ex) {
            this.logger.error("[getInterfacesObject] Exception occurred while generating valid interfaces object. Exception", ex);
        } finally {
            return {
                interfaces: interfaces,
                publicIP: publicIP
            };
        }
    },

    /**
     * Checks if the IP is not empty, mapped in mappings and a valid ip
     * @param {int} index Index of the Ip address field
     * @param {string} ipAddress Value of the Ip address
     * @param {json} mappedFields Field Mapping from the configuration
     * @returns boolean
     */
    getState: function(cmdbValue) {
        if (gs.nil(cmdbValue))
            return STATES.EMPTY;
        var isValid = cmdbValue.match(this.VALID_IP_REGEX);
        if (isValid)
            return STATES.VALID;
        return STATES.INVALID;
    },

    /**
     * Checks if the IP is not empty, mapped in mappings and a valid ip
     * @param {int} index Index of the Ip address field
     * @param {string} state State array
     * @param {string} hostname Hostname of the workload
     * @returns boolean
     **/
    canSyncIP: function(key, state, hostname) {
        switch (state) {
            case STATES.INVALID:
                if (key != "umw0")
                    this.logger.error("Skipping IP address " + key + " for workload with hostname " + hostname + " as there is an invalid IP address");
                else
                    this.logger.error("Skipping Public IP address for workload with hostname " + hostname + " as there is an invalid IP address");
                return false;
            case STATES.NOT_MAPPED_AND_VALID:
                if (key != "umw0")
                    this.logger.error("Skipping IP address " + key + " for workload with hostname " + hostname + " as it is not mapped in field mapping");
                else
                    this.logger.error("Skipping Public IP address for workload with hostname " + hostname + " as it is not mapped in field mapping");
                return false;
            case STATES.VALID:
                return true;
            default:
                return false;
        }
    },
    /**
     * Check whether conflict is there or not in the workload
     *
     * SUPERSEDED and now unreachable. Its only caller was the "Illumio Set Conflict" business
     * rule on the workload table, which is deactivated -- discovery sets conflicts itself in
     * IllumioDiscoverAndMapCMDBServers._insertObject, via the pure
     * IllumioDiscoveryUtils.evaluateConflict. Kept for reference until the dead-code cleanup
     * ticket removes it along with the other unreachable methods in this file. If you are
     * changing conflict logic, change evaluateConflict; this copy is not consulted.
     *
     * @param {GlideRecord} current GlideRecord of the Objectt
     * @param {JSON} mappedFields Object with the mapped fields
     * @returns true if there is any conflict else false
     */
    checkConflict: function(current, mappedFields) {
        try {

            if (!current || !mappedFields) {
                return false;
            }
            if (current.duplicate) {
                return false;
            }
            if (current.known_to_pce == 'unknown') {
                return true;
            }
            var sourceTable = current.getValue("source_table");
            var workloadFieldValueGr = new GlideRecordSecure(TABLE_PCE_WORKLOAD_FIELD_VALUE);
            workloadFieldValueGr.addQuery('illumio_pce_workload', current.getUniqueValue());
            workloadFieldValueGr.addQuery('illumio_label_dimension.key', "IN", mappedFields[sourceTable]);
            workloadFieldValueGr.query();

            while (workloadFieldValueGr.next()) {
                if (workloadFieldValueGr.getValue("cmdb_value") != workloadFieldValueGr.getValue("pce_value"))
                    return true;
            }

            if (current.getValue("known_to_pce") == "unmanaged") {
                var interfaces = JSON.parse(current.getValue("interfaces"));
                var visitedIPs = {},
                    key;

                if (!gs.nil(interfaces["umw0"]) && !gs.nil(interfaces["umw0"]["cmdb_value"]) && interfaces["umw0"]["cmdb_value"] != interfaces["umw0"]["pce_value"])
                    return true;

                for (key in interfaces) {
                    if (!gs.nil(interfaces[key]["pce_value"]))
                        visitedIPs[interfaces[key]["pce_value"]] = true;
                }

                for (key in interfaces) {
                    if (!gs.nil(interfaces[key]["cmdb_value"]) && !visitedIPs[interfaces[key]["cmdb_value"]])
                        return true;
                }

            }
            return false;
        } catch (ex) {
            this.logger.error("Exception while checking conflicts", ex);
        }
    },
    /**
     * Handles the error generated while any operation is in progress 
     * @param {integer} type Type of the error Client Side or Server side
     * @param {JSON} obj JSON object that accepts the GlideRecord of the caller, jobSysId if the type is client side and error
     */
    handleError: function(type, obj, current) {
        switch (type) {
            case CLIENT_ERROR_TYPE:
                gs.addErrorMessage(obj.message);
                this.logger.error(obj.message);
                if (current)
                    current.setAbortAction(true);
                break;
            case SERVER_ERROR_TYPE:
                break;
        }
    },
    /**
     * Validates the MID server and User to check if the JOb can start or not
     * @param {string} current GlideRecord of configuration table
     * @param {GlideRecord} midGr GlideRecord of the MID server
     * @returns {boolean} true if the validation is susccessful else false
     **/
    canStartJob: function(current, midGr) {
        var mid_server = midGr.getDisplayValue();
        if (!(midGr.status == MID_SERVER_UP_STATUS && midGr.validated == 'true')) {
            this.handleError(CLIENT_ERROR_TYPE, {
                message: "Configured MID server \"" + mid_server + "\" is either down or not validated"
            }, current);
            return false;
        }
        if (midGr.version + '' != MID_SERVER_VERSION) {
            this.handleError(CLIENT_ERROR_TYPE, {
                message: "Configured MID server \"" + mid_server + "\" is not up to date."
            }, current);
            return false;
        }
        //User roles validation
        var loggedUserGr = new GlideRecord('sys_user');
        loggedUserGr.addQuery('user_name', midGr.user_name);
        loggedUserGr.setLimit(1);
        loggedUserGr.query();
        if (loggedUserGr.next()) {
            var isMidUser = this.userHasRole(loggedUserGr.sys_id + '', MID_SERVER_USER_ROLE);
            var isIllumioMidUser = this.userHasRole(loggedUserGr.sys_id + '', ILLUMIO_MID_SERVER_ROLE);
            if (!isMidUser && isIllumioMidUser) {
                this.handleError(CLIENT_ERROR_TYPE, {
                    message: "The user which is configured in \"" + mid_server + "\" MID server does not have the 'mid_server' role."
                }, current);
                return false;
            }
            if (!isIllumioMidUser && isMidUser) {
                this.handleError(CLIENT_ERROR_TYPE, {
                    message: "The user which is configured in \"" + mid_server + "\" MID server does not have the 'x_illu2_illumio.mid_server_user' role."
                }, current);
                return false;
            }
            if (!isIllumioMidUser && !isMidUser) {
                this.handleError(CLIENT_ERROR_TYPE, {
                    message: "The user which is configured in \"" + mid_server + "\" MID server does not have the 'mid_server' and 'x_illu2_illumio.mid_server_user' roles."
                }, current);
                return false;
            }
        } else {
            this.handleError(CLIENT_ERROR_TYPE, {
                message: 'MID server user having user id ' + midGr.user_name + ' is not found in the Users(user_name) table.'
            }, current);
            return false;
        }
        return true;
    },

    /**
     * Checks if the user has the role
     * @param {string} userId User ID
     * @param {string} role Role to be checked
     * @returns {boolean} true if the user has the role else false
     **/
    userHasRole: function(u_id, role) {
        var userRoleGr = new GlideRecord('sys_user_has_role');
        userRoleGr.addQuery('user', u_id);
        userRoleGr.addQuery('role.name', role);
        userRoleGr.setLimit(1);
        userRoleGr.query();
        return userRoleGr.hasNext();
    },

    /**
     * Completes the process monitor with failed state
     * @param {String} jobSysId system id of the process monitor
     * @param {String} operation current operation
     * @param {String} message message to show in process monitor
     **/
    handleFailure: function(jobSysId, operation, message) {
        if (this.scheduledJobsGr.get(jobSysId)) {

            if (this.scheduledJobsGr.job_status == "cancelled") return;

            this.scheduledJobsGr.job_status = 'failed';
            this.scheduledJobsGr.logs += '\n' + operation;
            this.scheduledJobsGr.logs += '\nAuthentication failed';
            this.scheduledJobsGr.job_completed = new GlideDateTime();
            this.scheduledJobsGr.update();
            this.logger.error(message);
        } else {
            this.logger.error("Cannot find the scheduled job with sys_id: " + jobSysId);
        }
    },

    /**
     * Download the data from attachment
     * @param {string} tableName Name of the table to download attachment from
     * @param {string} tableSysId Sys id of the record
     * @returns Content of the attachment as a strin
     */
    downloadAttachmentData: function(tableName, tableSysId) {
        // Open the attachment on the record.
        var grAttachment = new GlideRecord('sys_attachment');
        grAttachment.addQuery('table_name', tableName);
        grAttachment.addQuery('table_sys_id', tableSysId);
        grAttachment.setLimit(1);
        grAttachment.query();
        if (!grAttachment.next()) {
            // Fail loudly rather than returning something the caller can parse. An empty
            // result would let 'Illumio Poll PCE Async Job Status' carry on and run
            // deleteMultiple() on the mapping table with this staging row's records
            // missing, which reads downstream as "these workloads are gone from the PCE".
            throw new Error('downloadAttachmentData: no attachment on ' + tableName +
                ' record ' + tableSysId + ', although json_data says <see_attachment/>.');
        }

        // getContent() opens, reads and closes the underlying stream itself, so no handle
        // is left open once this returns. getContentStream() hands back a
        // GlideScriptableInputStream instead, which exposes no close() to scoped script --
        // the file handle it opens can only be reclaimed by the node's GC, whenever that is.
        //
        // This also returns the whole body rather than readLine()'s first line. The payload
        // is a single-line JSON array today, so the two agree; if it ever were not, the old
        // form would have handed the caller a truncated string to JSON.parse.
        return new GlideSysAttachment().getContent(grAttachment);
    },

    /**
     * Query the case-sensitive GlideRecord 
     * @param {string} tableGr GlideRecord of the table
     * @param {string} key field of the table
     * @param {string} value value to be matched
     * @returns gr if found, else return JSON response as false
     */
    queryCaseSensitiveGr: function(tableGr, key, value, targetField) {
        while (tableGr.next()) {
            if (tableGr.getValue(key) == value) {
                return {
                    found: true,
                    returnValue: tableGr.getValue(targetField)
                };
            }
        }
        return {
            found: false
        };
    },

    /**
     * Persist records of  the provided configuration
     * @param {object} GlideRecord object of PCE configuration
     */
    persistLabelDimensions: function(pceConfig) {
        var labelDimensionGr = new GlideRecordSecure(TABLE_LABEL_DIMENSION);
        labelDimensionGr.addQuery("illumio_pce_configuration", pceConfig.getUniqueValue());
        labelDimensionGr.addNotNullQuery("href");
        labelDimensionGr.query();
        labelDimensionGr.setValue("isdeleted", false);
        labelDimensionGr.setWorkflow(false);
        labelDimensionGr.updateMultiple();
    },

    /**
     * Make REST API call to Illumio PCE
     * @params {String} the name of the RestMessage to be used
     * @params {String} the name of the HTTP Method to be used
     * @parmas {object} string parameters for the RESTMessage
     * @params {object} headers to be passed to the RestMessage
     * @params {object} body to be passed to the RestMessage
     * @params {String} the MID Server to be used
     * @returns {object} the response object returned by the API
     */
    makeRestCall: function(restMessage, httpMethod, stringParams, headers, body, midServer) {



        var apiCall = new sn_ws.RESTMessageV2(restMessage, httpMethod);

        apiCall.setRequestHeader('User-Agent', 'servicenow');

        if (!gs.nil(stringParams)) {
            Object.keys(stringParams).forEach(function(key) {
                apiCall.setStringParameter(key, stringParams[key]);
            });
        }
        if (!gs.nil(headers)) {
            Object.keys(headers).forEach(function(key) {
                apiCall.setRequestHeader(key, headers[key]);
            });
        }
        if (!gs.nil(body) && Object.keys(body).length > 1) {
            apiCall.setRequestBody(JSON.stringify(body));
        }
        if (!gs.nil(midServer)) {
            apiCall.setMIDServer(midServer);
            apiCall.setEccParameter("skip_sensor", "true");
        }
        return apiCall.executeAsync();
    },

    /**
     * Hit Illumio PCE API to get the label dimensions for a provided organisation
     * @param {String} pceConfig object of configuration
     * @returns {dict} Dict containing the status, response and response status code
     */
    getLabelDimensions: function(pceConfig) {
        try {
            var returnDict = {
                "status": false,
                "response": "",
                "statusCode": -1
            };

            if (!(pceConfig.mid_server.status == MID_SERVER_UP_STATUS && pceConfig.mid_server.validated == 'true')) {
                this.logger.error("The configured MID Server with configuration record " + pceConfig.getValue("name") + " is down.");
                return returnDict;
            }

            var inputs = {};
            inputs['pce_configuration'] = pceConfig; // GlideRecord of table: x_illu2_illumio_illumio_pce_conf 

            // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
            var actionTimeout = gs.getProperty('x_illu2_illumio.flow_action_timeout') || 30000;
            var result = sn_fd.FlowAPI.getRunner().action('x_illu2_illumio.fetch_label_dimensions').inForeground().withInputs(inputs).timeout(actionTimeout).run();
            var outputs = result.getOutputs();

            // Get Outputs:
            returnDict["statusCode"] = outputs['variable']; // String
            returnDict["response"] = JSON.parse(outputs['variable1']); // JSON
            returnDict["status"] = true;

        } catch (exc) {
            this.logger.error("Exception while making the API call to get the label dimensions for PCE configuration " + pceConfig.getValue("name") + ". Error - " + exc);
        }
        return returnDict;
    },

    /**
     * Create/Update the label dimension record with the provided details
     * @param {dict} contains the label dimension object from the API response obtained from Illumio PCE
     * @param {object} GlideRecord of PCE Configuration
     */
    createOrUpdateLabelDimensionRecord: function(details, pceConfig) {
        try {
            var labelDimensionGr = new GlideRecordSecure(TABLE_LABEL_DIMENSION);
            labelDimensionGr.addQuery("key", details["key"]);
            labelDimensionGr.addQuery("illumio_pce_configuration", pceConfig.getUniqueValue());
            labelDimensionGr.query();
            if (!labelDimensionGr.next()) {
                labelDimensionGr.initialize();
                labelDimensionGr.setValue("key", details["key"]);
                labelDimensionGr.setValue("illumio_pce_configuration", pceConfig.getUniqueValue());
            }
            if (!gs.nil(details["display_info"])) {
                labelDimensionGr.setValue("label_type_initial", details["display_info"]["initial"]);
                labelDimensionGr.setValue("display_name_plural", details["display_info"]["display_name_plural"]);
            }
            labelDimensionGr.setValue("display_name_singular", details["display_name"]);
            labelDimensionGr.setValue("href", details["href"]);

            labelDimensionGr.setValue("isdeleted", false);

            labelDimensionGr.setWorkflow(false);
            labelDimensionGr.update();
        } catch (exc) {
            this.logger.warn("Error occurred while creating/updating the record for Label Dimension " + details["key"] + ". ");
        }
    },

    /**
     * Fetch the details of label dimensions from PCE
     */
    fetchLabelDimensionsFromPCE: function() {
        try {
            var pceConfig = new GlideRecordSecure(TABLE_PCE_CONF);
            pceConfig.query();

            while (pceConfig.next()) {
                var responseDict = this.getLabelDimensions(pceConfig);
                if (responseDict && !responseDict["status"]) {
                    this.logger.error("Failed fetching of Label Dimensions from Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ".");
                    this.persistLabelDimensions(pceConfig);
                    continue;
                }
                var response = responseDict["response"];
                response_status = responseDict["statusCode"];

                if (response_status >= 200 && response_status < 300) {

                    // Iterate over each dimension and intialize record, if not already present, and update it.
                    for (var i = 0; i < response.length; i++) {
                        this.createOrUpdateLabelDimensionRecord(response[i], pceConfig);
                    }
                    this.logger.debug("Successfully fetched " + response.length + " label dimensions from Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ".");
                } else {
                    this.logger.error("Error while fetching label dimensions from Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ". Status code - " + response_status + ". Response - " + JSON.stringify(response));
                    this.persistLabelDimensions(pceConfig);
                }
            }
        } catch (exc) {
            this.logger.error("Exception while fetching label dimensions from PCE. " + exc);
        }
    },

    /**
     * Fetch all label dimensions and check if a label dimension with same key is already present on Illumio PCE
     * @param {String} key for the newly created label dimension
     * @param {String} pceConfig sys_id of the configuration record
     * @returns {Boolean} status of whether the label dimension has to be created
     */
    validateLabelDimensionCreation: function(key, pceConfigSysId) {
        try {
            var matchFound = false;

            var pceConfig = new GlideRecordSecure(TABLE_PCE_CONF);
            if (pceConfig.get(pceConfigSysId)) {
                var responseDict = this.getLabelDimensions(pceConfig);
                if (!responseDict["status"]) {
                    return matchFound;
                }
                response = responseDict["response"];
                response_status = responseDict["statusCode"];

                if (response_status >= 200 && response_status < 300) {

                    // Iterate over each dimension and intialize record, if not already present, and update it.
                    for (var i = 0; i < response.length; i++) {
                        this.createOrUpdateLabelDimensionRecord(response[i], pceConfig);

                        if (response[i]["key"] == key) {
                            matchFound = true;
                            this.logger.debug("A label dimension with key " + key + " is already present on Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ". Replacing the label dimension details with the ones obtained from Illumio PCE.");
                        }
                    }
                } else {
                    this.logger.error("Error while validating the creation of label dimension with key - " + key + " for the PCE configuration " + pceConfig.getValue("name") + ". Status code - " + response_status + ". Response - " + JSON.stringify(response));
                }
            }
        } catch (exc) {
            this.logger.error("Error while validating the creation of label dimension with key - " + key + ". Error - " + exc);
            return false;
        }
        return matchFound;
    },

    /**
     * Retry failed label dimension creation
     * When the label dimensions creation fails on PCE, this method is to be called with the next scheduled script execution while fetching the label dimensions.
     * This method would retry creating the label dimensions aaded on ServiceNow onto the coorelating Illumio PCE tenant.
     */
    retryFailedLabelDimensionCreation: function() {
        var labelDimensionGr = new GlideRecordSecure(TABLE_LABEL_DIMENSION);
        labelDimensionGr.addNullQuery("href");
        labelDimensionGr.query();
        while (labelDimensionGr.next()) {
            try {
                var details = {
                    "key": labelDimensionGr.getValue("key"),
                    "display_name_singular": labelDimensionGr.getValue("display_name_singular"),
                    "display_name_plural": labelDimensionGr.getValue("display_name_plural"),
                    "label_type_initial": labelDimensionGr.getValue("label_type_initial"),
                    "illumio_pce_configuration": labelDimensionGr.getValue("illumio_pce_configuration")
                };

                this.logger.debug("Trying to create label dimension " + details["key"] + " on Illumio PCE for PCE configuration " + details["illumio_pce_configuration"] + ".");

                var responseDict = this.createLabelDimensionsInPCE(details);
                if (responseDict["status"] && !gs.nil(responseDict["href"])) {
                    labelDimensionGr.setValue("href", responseDict["href"]);
                }

                // Mark the record to not be deleted
                labelDimensionGr.setValue("isdeleted", false);
                labelDimensionGr.setWorkflow(false);
                labelDimensionGr.update();
            } catch (exc) {
                this.logger.error("Error while retrying to create the label dimension " + labelDimensionGr.getValue("key") + ". Error - " + exc);
            }
        }
    },

    /**
     * Create a label dimension on Illumio PCE
     * @returns {dict} containing status and href
     */
    createLabelDimensionsInPCE: function(labelDimensionData) {
        var returnDict = {
            "status": false,
            "href": "",
        };
        try {
            var pceConfig = new GlideRecordSecure(TABLE_PCE_CONF);
            if (pceConfig.get(labelDimensionData["illumio_pce_configuration"])) {
                if (!(pceConfig.mid_server.status == MID_SERVER_UP_STATUS && pceConfig.mid_server.validated == 'true')) {
                    this.logger.error("The configured MID Server with configuration record " + pceConfig.getValue("name") + " is down.");
                    returnDict["status"] = false;
                    return returnDict;
                }

                var requestBody = {
                    "key": labelDimensionData["key"],
                    "display_name": labelDimensionData["display_name_singular"],
                    "display_info": {
                        "initial": labelDimensionData["label_type_initial"],
                        "display_name_plural": labelDimensionData["display_name_plural"]
                    }
                };

                var inputs = {};
                inputs['pce_configuration'] = pceConfig; // GlideRecord of table: x_illu2_illumio_illumio_pce_conf 
                inputs['request_body'] = JSON.stringify(requestBody); // JSON 

                // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
                var actionTimeout = gs.getProperty('x_illu2_illumio.flow_action_timeout') || 30000;
                var result = sn_fd.FlowAPI.getRunner().action('x_illu2_illumio.create_label_dimensions').inForeground().withInputs(inputs).timeout(actionTimeout).run();
                var outputs = result.getOutputs();

                // Get Outputs:
                var response = JSON.parse(outputs['response']); // JSON
                var response_status = outputs['status']; // String

                if (response_status >= 200 && response_status < 300) {
                    returnDict["href"] = response["href"];
                    this.logger.debug("Label dimension " + labelDimensionData["key"] + " created successfully on Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ".");
                    returnDict["status"] = true;
                } else if (response_status == 406) {
                    response = response[0];
                    this.logger.error("Error while creating label dimension " + labelDimensionData["key"] + " on Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ". " + response["message"] + "");
                    returnDict["status"] = false;
                } else {
                    this.logger.error("Error while creating label dimension " + labelDimensionData["key"] + " on Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ", it will be retried with the next scheduled script execution. Status code - " + response_status + ". Response - " + JSON.stringify(response));
                    returnDict["status"] = false;
                }
            }
        } catch (exc) {
            this.logger.error("Exception while creating label dimension on Illumio PCE. " + exc);
        }
        return returnDict;
    },

    /**
     * Update a label dimension on Illumio PCE
     * @returns {Boolean} containing status
     */
    updateLabelDimension: function(labelDimensionData) {
        try {
            var pceConfig = new GlideRecordSecure(TABLE_PCE_CONF);
            if (pceConfig.get(labelDimensionData["illumio_pce_configuration"])) {
                if (!(pceConfig.mid_server.status == MID_SERVER_UP_STATUS && pceConfig.mid_server.validated == 'true')) {
                    this.logger.error("The configured MID Server with configuration record " + pceConfig.getValue("name") + " is down.");
                    return false;
                }

                var body = {
                    "display_name": labelDimensionData["display_name_singular"],
                    "display_info": {
                        "initial": labelDimensionData["label_type_initial"],
                        "display_name_plural": labelDimensionData["display_name_plural"]
                    },
                };

                var inputs = {};
                inputs['pce_configuration'] = pceConfig; // GlideRecord of table: x_illu2_illumio_illumio_pce_conf 
                inputs['label_dimension_href'] = labelDimensionData["href"]; // String 
                inputs['request_body'] = JSON.stringify(body); // JSON 

                // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
                var actionTimeout = gs.getProperty('x_illu2_illumio.flow_action_timeout') || 30000;
                var result = sn_fd.FlowAPI.getRunner().action('x_illu2_illumio.update_label_dimensions').inForeground().withInputs(inputs).timeout(actionTimeout).run();
                var outputs = result.getOutputs();

                // Get Outputs:
                var response_status = outputs['status']; // String
                var response = JSON.parse(outputs['response']); // JSON

                if (response_status >= 200 && response_status < 300) {
                    this.logger.debug("Label Dimension " + labelDimensionData["key"] + " updated successfully on Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ".");
                    return true;
                } else {
                    this.logger.error("Error while updating label dimension " + labelDimensionData["key"] + " on Illumio PCE for PCE configuration " + pceConfig.getValue("name") + ". Status code - " + response_status + ". Response - " + JSON.stringify(response));
                    return false;
                }
            }
        } catch (exc) {
            this.logger.error("Exception while updating label dimension on Illumio PCE. " + exc);
        }
        return false;
    },

    /**
     * Get the SysId of PCE Configuration record
     * @param {string} jobSysId
     * @returns SysId of the PCE Configuration record
     */
    getConfigurationId: function(jobSysId) {
        var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
        if (jobGr.get(jobSysId)) {
            return jobGr.getValue('illumio_pce_configuration');
        }
    },

    /**
     * prepare workload object with all the values
     * @param {Object} checkedRecords array of all selected workload's sys_ids 
     * @returns {Object}
     */
    getWorkloadData: function(checkedRecords) {
        var retObject = {},
            count = 0,
            configUtil = new IllumioGetPCEConfiguration(),
            thresholdLimit = new IllumioThresholdLimit(),
            autoSyncUtil = new IllumioAutoSyncWithPCE(),
            wlTypeOpMap = {
                "managed": "update",
                "unmanaged": "update",
                "unknown": "create"
            },
            cancelJobOnLimitExceed = false,
            limitExceeded = false,
            limitError = false,
            limitErrorMessage = '',
            syncUtils = new IllumioSyncUtils(),
            logMessage = {};
        // for each configuration fetch field mapping
        for (var configSysId in checkedRecords) {
            var workloadGr = new GlideRecordSecure(TABLE_PCE_WORKLOAD);
            var arrRecords = checkedRecords[configSysId],
                retVal = [];
            var mappedFields = configUtil.getLabelDimensionsBySourceTable(configSysId);

            var wlLimitObject;
            try {
                wlLimitObject = thresholdLimit.getThresholdLimit(configSysId);
            } catch (limitEx) {
                // Limits that cannot be resolved are not the same as no limits. Nothing is
                // returned for any configuration, so the caller cannot sync a partial set under
                // a threshold nobody could read.
                limitError = true;
                limitErrorMessage = 'Threshold limits could not be resolved. Nothing was synced.';
                limitExceeded = true;
                this.logger.error('[getWorkloadData] ' + limitErrorMessage + ' ' + limitEx);
                retObject = {};
                count = 0;
                cancelJobOnLimitExceed = true;
                break;
            }

            var isLimitExceed = false;

            // for each sys_id prepare workload object
            for (var arrIndex = 0, len = arrRecords.length; arrIndex < len; arrIndex++) {
                workloadGr.initialize();
                if (workloadGr.get(arrRecords[arrIndex]) && workloadGr.getValue("duplicate") == "0") {
                    try {
                        var wlType = workloadGr.getValue("known_to_pce");
                        var operation = wlTypeOpMap[wlType];

                        // check if limit is configured and exceeded
                        if (syncUtils.hasOperationBudget(wlLimitObject, operation)) {

                            // prepare workload object
                            var wlObject = this.prepareWorkloadObject(workloadGr, mappedFields);

                            // prepare label data
                            wlObject = autoSyncUtil.getUseCreateLabelsList(configSysId, wlObject, wlObject.label_data);
                            var createLabelLength = wlObject.createlabels.length;

                            // check if label creation limit exceeds
                            if (syncUtils.hasLabelCreationBudget(wlLimitObject, createLabelLength)) {

                                // update limits
                                syncUtils.consumeBudget(wlLimitObject, operation, createLabelLength);
                                retVal.push(wlObject);
                            } else {
                                isLimitExceed = true;
                                wlLimitObject["wlLimit"]["labelCreateLimitExceeded"] = true;

                                if (wlLimitObject.cancelJobOnLimitExceed) {
                                    retVal = [];
                                    cancelJobOnLimitExceed = true;
                                    break;
                                }
                            }
                        } else {
                            isLimitExceed = true;
                            wlLimitObject["wlLimit"][operation + "LimitExceeded"] = true;

                            if (wlLimitObject.cancelJobOnLimitExceed) {
                                retVal = [];
                                cancelJobOnLimitExceed = true;
                                break;
                            }
                        }
                    } catch (err) {
                        this.logger.info("Exception occurred while preparing workload object. Error", err);
                    }
                }
            }

            // log info message
            if (isLimitExceed) {
                limitExceeded = true;
                logMessage[configSysId] = this.logLimitExceedMessage(wlLimitObject, configSysId);
            }
            retObject[configSysId] = retVal;
            count += retVal.length;
        }

        return {
            filteredRecords: retObject,
            totalRecords: count,
            cancelJobOnLimitExceed: cancelJobOnLimitExceed,
            limitExceeded: limitExceeded,
            // limitExceeded means "a configured limit was hit". limitError means the limits
            // could not be read at all -- a different thing that used to be reported as the
            // first one, sending the operator to check a threshold that was never the problem.
            limitError: limitError,
            limitErrorMessage: limitErrorMessage,
            logMessage: logMessage
        };
    },

    // Phase 2 of the sync pipeline -- turning workload sys_ids into finished PCE payload
    // objects -- moved out to IllumioSyncBuildUtils.prepareWorkloadsForPCE. It was the one
    // function every sync and every deletion passes through, and it was buried in the middle
    // of PCE configuration, job records, attachments and discovery. Same move that took the
    // Sync Filter evaluator (phase 1) out to IllumioSyncFilterUtils; this is the other half.
    //
    // No delegating wrapper left behind on purpose. A wrapper is how this file became
    // coordination of everything in the first place.

    /**
     * Log message for threshold limit exceeded
     * @param {Object} wlLimitObject workload limit object
     * @param {String} configSysId sys_id of the PCE Configuration
     */
    logLimitExceedMessage: function(wlLimitObject, configSysId) {
        var message = [];

        if (wlLimitObject["wlLimit"]["createLimitExceeded"]) {
            message.push("workload creation");
        }

        if (wlLimitObject["wlLimit"]["updateLimitExceeded"]) {
            message.push("workload modification");
        }

        if (wlLimitObject["wlLimit"]["deleteLimitExceeded"]) {
            message.push("workload deletion");
        }

        if (wlLimitObject["wlLimit"]["labelCreateLimitExceeded"]) {
            message.push("label creation");
        }

        if (message.length > 1) {
            message = message.slice(0, -1).join(", ") + " and " + message.slice(-1);
            message += " limits have";
        } else {
            message += " limit has";
        }

        if (!wlLimitObject.cancelJobOnLimitExceed)
            message = "One or more workloads are skipped as " + message + " exceeded";
        else
            message = "Cancelled the job as " + message + " exceeded";

        this.logger.info(message + " for Illumio PCE Configuration with sys_id " + configSysId);
        return message;
    },

    /**
     * prepare workload object
     * @param {GlideRecord} workloadGr GlideRecord of Workload
     * @param {Object} mappedFields JSON object of mapped fields
     * @returns {Object}
     */
    /**
     * A repository instance cached on this IllumioUtils, for the label dimension map alone.
     *
     * Lazy rather than built in initialize, because IllumioUtils is constructed all over the
     * codebase by callers that never touch a label and should not pay for a repo -- and because
     * IllumioSyncRepoUtils constructs IllumioSyncUtils, which is a cycle this file keeps lazy on
     * purpose (same rule as IllumioSyncBuildUtils.initialize).
     *
     * @returns {Object} IllumioSyncRepoUtils
     */
    _labelDimensionRepo: function() {
        if (!this._repo) {
            this._repo = new IllumioSyncRepoUtils();
        }
        return this._repo;
    },

    prepareWorkloadObject: function(workloadGr, mappedFields) {
        var workloadObject = this.prepareWorkloadShell(workloadGr, mappedFields);
        var labelValues = {};

        // One query for one workload. The chunked sync pipeline does NOT come through here --
        // it builds the same map for a whole chunk in a single query
        // (IllumioSyncRepoUtils.getLabelValuesByWorkload) and calls selectLabelData itself.
        //
        // The dimension key comes from the cached map rather than a dot-walk, for the reason
        // given on IllumioSyncRepoUtils.getDimensionKeyBySysId: a dot-walk inside a `next()` loop
        // is a record load per row, not a join. The stake is far smaller here -- this path is the
        // "sync checked records" UI Action, bounded by what a user ticks in a list -- but it is
        // the same defect and there is no reason to leave one copy of it behind. The repo is
        // cached on `this` so the caller's loop over the checked records builds the map once.
        var dimensionKeyBySysId = this._labelDimensionRepo().getDimensionKeyBySysId();

        var labelGr = new GlideRecordSecure(TABLE_PCE_WORKLOAD_FIELD_VALUE);
        labelGr.addQuery("illumio_pce_workload", workloadObject["sys_id"]);
        labelGr.query();
        while (labelGr.next()) {
            var labelDimensionKey =
                dimensionKeyBySysId[labelGr.getValue("illumio_label_dimension")] || "";
            if (labelDimensionKey === "") {
                continue;
            }
            labelValues[labelDimensionKey] = {
                cmdb_value: labelGr.getValue("cmdb_value"),
                pce_value: labelGr.getValue("pce_value")
            };
        }

        workloadObject["label_data"] = new IllumioSyncUtils().selectLabelData(
            labelValues, workloadObject["updateFields"]);

        return workloadObject;
    },

    /**
     * Everything a workload object holds except its labels.
     *
     * Split out of prepareWorkloadObject because labels are the part the chunked sync pipeline
     * resolves in bulk: it needs the record-derived fields row by row (getInterfacesObject wants
     * the GlideRecord) but the label values once per chunk. Callers that want both in one call
     * should keep using prepareWorkloadObject.
     *
     * @param {GlideRecord} workloadGr GlideRecord positioned on a Workload
     * @param {Object} mappedFields Output of IllumioGetPCEConfiguration.getLabelDimensionsBySourceTable
     * @returns {Object} Workload object without label_data
     */
    prepareWorkloadShell: function(workloadGr, mappedFields) {
        var workloadFields = ["sys_id", "hostname", "known_to_pce", "conflicts", "duplicate", "pce_workload_href", "source_table"];
        var workloadObject = {};

        for (var fieldIndex in workloadFields) {
            workloadObject[workloadFields[fieldIndex]] = workloadGr.getValue(workloadFields[fieldIndex]);
        }
        // set update fields
        workloadObject["updateFields"] = mappedFields[workloadObject["source_table"]];

        // add interface data
        if (workloadObject["known_to_pce"] != "managed") {
            var interfaceObject = this.getInterfacesObject(workloadGr);
            workloadObject["interfaces"] = interfaceObject.interfaces;
            workloadObject["ip_address"] = interfaceObject.publicIP;
        }

        return workloadObject;
    },


    /**
     * Has the user cancelled this job?
     *
     * Not to be confused with GetLabelGroupsAjax.getCancelledJobStatus, which despite the
     * name it used to share with this one asks the opposite question -- whether the job is
     * still running and so can be cancelled -- and answers the Cancel Scheduled Job dialog.
     * @param {sys_id} jobSysId System id of the scheduled job
     * @returns {Boolean} true when the job has been cancelled
     **/

    isJobCancelled: function(jobSysId) {

        /**
         * This method is called internally during discovery and sync operations.
         * Hence we do not need ACLs. Use GlideRecord to speedup.
         */
        var scheduledJobGr = new GlideRecord(TABLE_SCHEDULED_JOBS);
        if (scheduledJobGr.get(jobSysId)) {
            return scheduledJobGr.getValue('job_status') == 'cancelled';
        }

        return false;
    },

    /**
     * The job currently running, if any.
     *
     * SCOPED TO A PCE CONFIGURATION when given one. It was unconditionally global, and that was
     * a deliberate choice resting on two shared resources that a second concurrent run would
     * corrupt:
     *
     *   1. IllumioSyncRepoUtils.deleteStalePayloadRows swept "every row that is not this job"
     *      from tables with no configuration column, so a second run deleted the first's
     *      in-flight payload rows. Fixed: the sweep is now scoped by whether the owning job is
     *      still open, so a concurrent run's rows are not candidates.
     *   2. IllumioGeneratePreviewFile._sweepOrphanFiles deleted every prefix-matching temp file
     *      on the MID Server, so a second preview deleted the first's part-written file. Fixed:
     *      the sweep now only considers files older than ORPHAN_MIN_AGE_MS, and an assembling
     *      file is seconds old by definition.
     *
     * Both were the same mistake -- "anything that is not mine is dead" -- and this guard was the
     * thing holding them together. With both fixed, the global scope was no longer protecting
     * anything; it was only stopping an operator from previewing configuration B while
     * configuration A ran a long sync, which was the accepted consequence and is now unnecessary.
     *
     * Four entry points were already per-configuration and always had been (IllumioStartDiscovery,
     * Illumio Data Collection, IllumioDeletionHandler, IllumioManageJobs), so "one job at a time"
     * was never actually true instance-wide. That mismatch is what made both bugs reachable.
     *
     * CALLING IT WITH NO ARGUMENT STILL SEARCHES EVERY CONFIGURATION, on purpose. If a caller
     * passes an undefined variable by mistake it blocks too much rather than too little, which is
     * the recoverable direction for a guard.
     *
     * Runs as GlideRecord, not GlideRecordSecure, and that is the security-relevant choice rather
     * than an oversight. This is a guard: a caller who cannot read the scheduled jobs table must
     * not therefore be told the instance is idle and allowed to start a second job. The client
     * half of the guard reaches this through IllumioUtilsAJAX, but it only ever learns that
     * something is running and what it is called -- which anyone able to press the button may
     * know.
     *
     * @param {String} [configSysId] PCE Configuration to limit the search to. Omit to search all.
     * @returns {Object} { sysId, jobType, startedAt, scopedToConfig } for the oldest running job,
     *                   or null when nothing is running
     */
    getRunningJob: function(configSysId) {
        var scoped = !gs.nil(configSysId);

        var jobGr = new GlideRecord(TABLE_SCHEDULED_JOBS);
        jobGr.addQuery('job_status', 'running');

        if (scoped) {
            jobGr.addQuery('illumio_pce_configuration', configSysId);
        }

        // Oldest first: if several are somehow running, the one that has been stuck longest is
        // the one the user needs to know about.
        jobGr.orderBy('job_started');
        jobGr.setLimit(1);
        jobGr.query();

        if (!jobGr.next()) {
            return null;
        }

        return {
            sysId: jobGr.getUniqueValue(),
            jobType: jobGr.getDisplayValue('job_type') || jobGr.getValue('job_type') || 'Unknown',
            startedAt: jobGr.getDisplayValue('job_started') || '',
            scopedToConfig: scoped
        };
    },

    /**
     * The message shown when the running-job guard refuses.
     *
     * Shared so the client-side check, the server-side check and the job log all say the same
     * thing, and so all three name the blocking job -- "another job is running" leaves the user
     * with nothing to act on, and the action they need is usually Cancel Scheduled Job.
     *
     * The wording follows the scope the caller actually asked for. It used to say "Only one job
     * may run at a time" unconditionally, which is now wrong for the scoped callers and was
     * always misleading for the four entry points that had their own per-configuration guard --
     * a user told that would go looking for a job that does not exist on their configuration.
     *
     * @param {Object} runningJob Result of getRunningJob
     * @returns {String} Message naming the job and when it started
     */
    describeRunningJob: function(runningJob) {
        if (!runningJob) {
            return '';
        }

        var started = runningJob.startedAt ? ', started ' + runningJob.startedAt : '';

        if (runningJob.scopedToConfig) {
            return 'Another Illumio job is already running for this PCE Configuration (' +
                runningJob.jobType + started + '). Only one job may run at a time per ' +
                'configuration. Wait for it to finish, or cancel it from Scheduled Jobs.';
        }

        return 'Another Illumio job is already running (' + runningJob.jobType + started +
            '). Only one job may run at a time. Wait for it to finish, or cancel it from ' +
            'Scheduled Jobs.';
    },

    /**
     * Get require parameter to create HttpClient object for given configuration
     * @param {String} configSysId SysId of PCE Configuration
     * @returns {Object} of Required parameters
     **/

    getHttpConfiguration: function(configSysId) {
        var pceConfig = new GlideRecordSecure(TABLE_PCE_CONF);
        if (pceConfig.get(configSysId)) {

            return {
                illumio_pce_configuration_id: configSysId,
                pce_url: String(pceConfig.pce_url),
                pce_authorization: gs.base64Encode(pceConfig.username.getDecryptedValue() + ':' + pceConfig.secret_key.getDecryptedValue()),
                time_zone: gs.getSession().getTimeZoneName(),
                enable_pce_mid_proxy: pceConfig.getValue("enable_proxy_between_pce_and_mid_server"),
                org_id: pceConfig.getValue("organization_id") || "1"
            };
        }
    },

