    DELETION_PREVIEW_PREFIX: 'DELETION-PREVIEW-',
    DELETION_PREVIEW_MAX_AGE_MINUTES: 30,

    /**
     * What deletion preview, if any, this configuration currently holds.
     *
     * Two questions and no others: is there a DELETION-PREVIEW-* attachment on this PCE
     * Configuration, and how old is it. The prefix is part of the QUERY rather than a test applied
     * to every attachment on the record, so nothing else on the record is read or reasoned about.
     * Under the one-attachment-per-record rule (IllumioPreviewUtils._deleteExistingPreview clears
     * the record before every run) there is nothing else to reason about anyway -- counting the
     * other files only ever produced a refusal message that guessed at why.
     *
     * Ordered newest-first so the first row decides. That ordering is the fix for the original
     * defect: the gate used to return on the first prefix match in whatever order the query came
     * back, so a stale file sitting beside a fresh one refused a preview the user had just
     * generated and was looking at.
     *
     * A single-filter deletion preview attaches to the Sync Filter, not here, and deliberately
     * does not satisfy this gate -- see IllumioPreviewUtils.prefixForType.
     *
     * @param {String} configSysId sys_id of the PCE Configuration
     * @returns {Object} { fresh, found, fileName, ageMinutes }
     */
    deletionPreviewStatus: function(configSysId) {
        var status = {
            fresh: false,
            found: false,
            fileName: '',
            ageMinutes: -1
        };

        var gr = new GlideRecord('sys_attachment');
        gr.addQuery('table_name', TABLE_PCE_CONF);
        gr.addQuery('table_sys_id', configSysId);
        gr.addQuery('file_name', 'STARTSWITH', this.DELETION_PREVIEW_PREFIX);
        gr.orderByDesc('sys_created_on');
        gr.setLimit(1);
        gr.query();

        if (!gr.next()) {
            return status;
        }

        var createdOn = new GlideDateTime(gr.getValue('sys_created_on'));
        status.found = true;
        status.fileName = gr.getValue('file_name') || '';
        status.ageMinutes =
            (new GlideDateTime().getNumericValue() - createdOn.getNumericValue()) / 60000;
        status.fresh = status.ageMinutes <= this.DELETION_PREVIEW_MAX_AGE_MINUTES;

        return status;
    },

    /**
     * Why the deletion preview gate is refusing, in terms the user can act on.
     *
     * @param {Object} status Return value of deletionPreviewStatus
     * @returns {String}
     */
    describeDeletionPreviewRefusal: function(status) {
        if (status.found) {
            return 'The deletion preview on this PCE Configuration is ' +
                Math.floor(status.ageMinutes) + ' minutes old (file "' + status.fileName +
                '"). Deletion requires one no older than ' +
                this.DELETION_PREVIEW_MAX_AGE_MINUTES + ' minutes. Generate a new one.';
        }

        return 'No deletion preview found on this PCE Configuration. Run Preview Workload ' +
            'Deletion here and wait for the CSV to be attached -- the ' +
            this.DELETION_PREVIEW_MAX_AGE_MINUTES + '-minute clock starts when the MID Server ' +
            'uploads it, not when the button is pressed. A preview generated from a single Sync ' +
            'Filter attaches to that filter and does not satisfy this gate.';
    },

    /**
     * Whether a deletion preview attachment exists for this configuration and is recent enough.
     *
     * The safety gate in front of a non-reversible action: the user must have looked at what
     * would be deleted within the last 30 minutes. It is a pre-flight check, so it belongs to
     * whoever is about to start the job -- not to the job itself. prepareDeletionPayload used to
     * own it, which meant the check could only run after phase 1 and phase 2 had already done
     * their work.
     *
     * @param {String} configSysId sys_id of the PCE Configuration
     * @returns {Boolean} true when a DELETION-PREVIEW- attachment under 30 minutes old exists
     */
    hasFreshDeletionPreview: function(configSysId) {
        return this.deletionPreviewStatus(configSysId).fresh;
    },

    /**
     * Decide which workload each deletion Sync Filter matched becomes, and write it to the
     * deletion payload table.
     *
     * R14 + P0-1, done as one change because separately neither delivers anything: moving onto
     * prepareWorkloadsForPCE without moving the payload off the ECC message leaves the whole result
     * set in memory and in the message anyway, and the message is the ceiling that matters.
     *
     * Shared with the sync path: phase 1, chunking, the chunk drain, threshold accounting.
     * Deletion-only: the eligibility rules in _buildDeletionShell and the row shape. Labels are
     * skipped wholesale -- deletion reads three columns and never looks at one.
     *
     * Runs inside the deletion job (IllumioStartWorkloadDeletion), never in a user transaction,
     * so jobSysId is always available to log progress against.
     *
     * @param {String} configSysId sys_id of the PCE Configuration
     * @param {String} jobSysId sys_id of the deletion scheduled job, for progress logging
     * @returns {Object} { success, message, payloadRowCount, deletionCount, unpairCount,
     *   skippedCount, thresholdExceeded, cancelJob }
     *
     * payloadRowCount is a count, not the sys_ids. Since R33 the rows carry the job reference and
     * both consumers -- the MID Server and the withdrawal paths -- query on it, so the only thing
     * a list was still answering was "is there anything to dispatch".
     */
    prepareDeletionPayload: function(configSysId, jobSysId) {
        var result = {
            success: false,
            message: '',
            payloadRowCount: 0,
            deletionCount: 0,
            unpairCount: 0,
            skippedCount: 0,
            thresholdExceeded: false,
            cancelJob: false
        };

        try {
            // The preview gate ran in the UI Action before this job was created -- see
            // hasFreshDeletionPreview. Re-checking here would fail a job the user has already
            // been told started, purely because the scheduler queued it for a few minutes.

            // Get eligible workloads from deletion sync filters. Identical to the sync path's
            // phase 1 apart from the filter type.
            //
            // The progress sink is what R22 was for: phase 1 now runs inside the job, so it has
            // a record to log to, and a deletion that spends minutes matching says what it is
            // matching instead of going quiet.
            var progress = this.jobProgressLogger(jobSysId);

            // Per-row commentary. One line per PAYLOAD_ROW_SIZE workloads is 100 lines on a 100k
            // deletion, so it goes to syslog and the job record keeps only the "Payload Batches:
            // N" denominator and the Summary. See jobTraceLogger.
            var trace = this.jobTraceLogger(jobSysId);

            var syncFilterResult = new IllumioSyncFilterUtils()
                .getEligibleWorkloadSysIdsByConfig(configSysId, 'deletion', progress);

            if (!syncFilterResult.hasFilter) {
                result.message = 'No active deletion sync filters configured for this PCE Configuration.';
                return result;
            }

            if (!syncFilterResult.sysIds || syncFilterResult.sysIds.length === 0) {
                result.message = 'No workloads match the active deletion sync filter criteria.';
                return result;
            }

            // No count here any more. Phase 1 ends on "Eligible Workloads: N" and this said the
            // same number again under a different name. current_operation still moves, because
            // that is a field rather than a log line.
            if (!gs.nil(jobSysId)) {
                this.updateJobRecord(jobSysId, {
                    current_operation: 'Building deletion payload'
                });
            }

            var self = this;
            var syncUtils = new IllumioSyncUtils();
            var repo = new IllumioSyncRepoUtils(syncUtils);

            // Before the first row is written, not after the run: rows from a dead run are
            // unreachable -- every consumer queries by job -- so nothing else will ever remove
            // them. The same sweep the preview export has always done, on its own table.
            repo.deleteStalePayloadRows(
                syncUtils.DELETION_PAYLOAD_TABLE, jobSysId, progress);

            // One row per PAYLOAD_ROW_SIZE workloads, NOT one per phase-2 window. The two used to
            // be the same thing, which made every row the window size -- 500 -- and every PCE
            // bulk call half of what the endpoint accepts. A window is how much of the workload
            // table is in memory at once; a row is how much the MID Server sends in one call.
            // See PAYLOAD_ROW_SIZE in IllumioSyncUtils.
            //
            // Because a row now spans two windows, onWindowEnd no longer empties the bundle and
            // the caller has to flush the tail itself. That flush is below, on the success path.
            var bundle = { retiredWorkloads: {}, vensToUnpair: [], isDeletion: true };
            var bundleCount = 0;

            // Per-STEP timing, the way the discovery logs do it: rowStartedAt is reset by every
            // flush, so each "Payload Prepared" line times its own row -- the scan that filled it
            // plus the insert -- rather than the whole run so far. phase2StartedAt is the one
            // cumulative clock, and it appears once, on the Summary.
            var phase2StartedAt = new Date().getTime();
            var rowStartedAt = phase2StartedAt;

            // Predicted from the eligible count, so the "x of N" below has its denominator before
            // the first row is written. It is a ceiling rather than a promise: workloads dropped
            // by `duplicate=false`, by the shell builder or by the threshold never reach a bundle,
            // so a run can legitimately finish at 7 of 8.
            var expectedRows = Math.ceil(
                syncFilterResult.sysIds.length / syncUtils.PAYLOAD_ROW_SIZE);

            progress('Payload Batches: ' + expectedRows);

            var flush = function() {
                if (bundleCount === 0) {
                    return;
                }

                // The job reference is stamped on the row because it is the ONLY thing connecting
                // the row to this run -- the ECC message does not carry the sys_ids any more, so
                // a row written without it is invisible to the MID Server.
                var extraFields = {};
                extraFields[syncUtils.PAYLOAD_JOB_FIELD] = jobSysId;

                var rowSysId = repo.insertPayloadRow(
                    syncUtils.DELETION_PAYLOAD_TABLE, JSON.stringify(bundle), extraFields);

                // Thrown, not logged-and-continued: a lost row is a set of workloads that will
                // never reach the MID Server, and carrying on would report a success count that
                // does not match what gets deleted. The catch below withdraws the rest.
                if (gs.nil(rowSysId)) {
                    throw 'Error while inserting record in deletion payload table';
                }

                result.payloadRowCount++;

                // The insert used to be silent, so a deletion that spent minutes writing rows
                // showed nothing between the end of phase 1 and the handoff to the MID Server.
                // The job record keeps "Payload Batches: N" and the Summary; this per-row line is
                // the detail behind them and goes to syslog.
                trace('Payload Prepared: ' + result.payloadRowCount + '/' + expectedRows +
                    syncUtils.since(rowStartedAt));

                bundle = { retiredWorkloads: {}, vensToUnpair: [], isDeletion: true };
                bundleCount = 0;
                rowStartedAt = new Date().getTime();
            };

            // syncUtils and repo passed in rather than left to default: without them this builds
            // a second pair alongside the ones two lines up, and any per-run cache they hold
            // (getDimensionKeyBySysId) would be built twice. Harmless on this path today because
            // skipLabelData means the label map is never asked for, but relying on that is how a
            // cache quietly stops being one.
            var outcome = new IllumioSyncBuildUtils(syncUtils, repo).prepareWorkloadsForPCE({
                pceConfigSysId: configSysId,
                sysIds: syncFilterResult.sysIds,
                // Duplicate workload records are excluded here rather than deduplicated by
                // pce_workload_href afterwards. The old code kept a run-wide href map to do that,
                // which is exactly the O(all matched workloads) structure this change exists to
                // remove, and `duplicate` is the column that marks the only way two records can
                // share an href. Same predicate the sync path uses for the same reason.
                chunkQuery: 'duplicate=false',
                skipCriticalLabels: false,
                skipLabelData: true,
                applyThreshold: true,
                operation: 'delete',
                // Kept from when this ran inline in the user's transaction. It now runs in a
                // Script Action, so ACLs evaluate as system and this reads the same rows
                // GlideRecord would. Left in place deliberately rather than flipped as a side
                // effect of moving the work off the browser; who may start a deletion is
                // enforced by the UI Action, the same way it is for sync.
                secure: true,
                // Phase 2's only job-record line is its reconciliation, and only when workloads
                // were dropped between the two phases. The per-row "Payload Prepared" lines come
                // from flush() below, which is the side that knows how many rows there will be.
                onProgress: progress,
                buildShell: function(workloadGr) {
                    return self._buildDeletionShell(workloadGr, result);
                },
                appendRow: function(workloadObject) {
                    if (workloadObject.known_to_pce === 'managed') {
                        bundle.vensToUnpair.push(workloadObject.ven_href);
                        result.unpairCount++;
                    } else {
                        // The value is a placeholder, not data. This is a SET of PCE hrefs
                        // written as an object because ES5 has no Set; the MID Server iterates
                        // the keys (IllumioUpdateWorkloads, `for (var hrefKey in
                        // retiredWorkloads)`) and has never read a value. It used to hold the
                        // ServiceNow sys_id, which nothing consumed and which was roughly half
                        // the serialized payload -- 34 bytes of quoted sys_id per workload, so
                        // ~34 KB on every 1000-workload row.
                        bundle.retiredWorkloads[workloadObject.pce_workload_href] = 1;
                        result.deletionCount++;
                    }

                    bundleCount++;

                    // Flushed on size rather than on the window boundary, which is what lets a
                    // row reach PAYLOAD_ROW_SIZE at all -- a window only ever holds
                    // WORKLOAD_CHUNK_SIZE of them.
                    if (bundleCount >= syncUtils.PAYLOAD_ROW_SIZE) {
                        flush();
                    }
                }
            });

            if (outcome.cancelJob) {
                // The rows already written describe deletions that must not happen.
                var withdrawn = repo.deletePayloadRowsForJob(
                    syncUtils.DELETION_PAYLOAD_TABLE, jobSysId);
                this.logger.info('[prepareDeletionPayload] Threshold limit exceeded, withdrew ' +
                    withdrawn + ' payload record(s)');

                result.payloadRowCount = 0;
                result.thresholdExceeded = true;
                result.cancelJob = true;
                result.message = 'Deletion threshold limit exceeded. Job will be cancelled.';
                return result;
            }

            // The tail. A payload row spans windows now, so the walk almost always ends with a
            // partial bundle in hand -- without this the last 1..999 workloads would be counted
            // in the summary and never sent. Deliberately after the cancelJob return above: on
            // that path the bundle describes deletions that must not happen, and writing it out
            // just to delete it again is work done to be undone.
            flush();

            result.skippedCount += outcome.skippedLimit;
            result.thresholdExceeded = outcome.limitExceeded;

            if (result.thresholdExceeded) {
                result.message = 'Deletion threshold limit exceeded. Some workloads were not included.';
            } else {
                result.message = result.deletionCount + ' workload(s) for deletion, ' + result.unpairCount + ' workload(s) for unpair' +
                    (result.skippedCount > 0 ? ', ' + result.skippedCount + ' skipped' : '');
            }

            result.success = true;
            progress('Summary: ' + result.message + syncUtils.since(phase2StartedAt));
            this.logger.info('[prepareDeletionPayload] ' + result.message);
        } catch (ex) {
            this.logger.error('[prepareDeletionPayload] Exception: ' + ex);
            result.message = 'Exception occurred: ' + ex;

            // Rows are written as the scan proceeds, so an exception part-way through leaves
            // real rows behind for a job that will never be dispatched. The caller only
            // withdraws on the paths where this returned success, so clean up here.
            // payloadRowCount is non-zero only once repo/syncUtils have been assigned.
            if (result.payloadRowCount > 0) {
                try {
                    var abandoned = repo.deletePayloadRowsForJob(
                        syncUtils.DELETION_PAYLOAD_TABLE, jobSysId);
                    this.logger.info('[prepareDeletionPayload] Withdrew ' + abandoned +
                        ' payload record(s) after exception');
                } catch (cleanupEx) {
                    this.logger.error('[prepareDeletionPayload] Failed to withdraw payload records: ' +
                        cleanupEx);
                }
                result.payloadRowCount = 0;
            }
        }

        return result;
    },

    /**
     * The three columns a deletion acts on, or null for a workload it cannot act on.
     *
     * This is the "what a row becomes" half of the phase-2 parameterisation for deletion. It is
     * deliberately not prepareWorkloadShell: that builds the whole sync object off the mapped
     * fields, and deletion consults none of it.
     *
     * **Behaviour change.** A managed workload with no ven_href is rejected HERE, before
     * threshold accounting. The pre-R14 code decremented the delete budget first and only then
     * discovered it had nothing to unpair, so every such workload silently consumed one unit of
     * a limit that exists to cap real deletions.
     *
     * @param {GlideRecord} workloadGr Workload record
     * @param {Object} tally Accumulator whose skippedCount is incremented on rejection
     * @returns {Object} Deletion row, or null to drop the workload
     */
    _buildDeletionShell: function(workloadGr, tally) {
        var knownToPce = workloadGr.getValue('known_to_pce');
        var pceHref = workloadGr.getValue('pce_workload_href');
        var venHref = workloadGr.getValue('ven_href');

        // Only a workload the PCE knows about can be deleted or unpaired there.
        if (knownToPce !== 'managed' && knownToPce !== 'unmanaged') {
            tally.skippedCount++;
            return null;
        }

        if (gs.nil(pceHref)) {
            tally.skippedCount++;
            return null;
        }

        // Managed means paired: the VEN is unpaired instead of the workload being deleted, so
        // with no ven_href there is no operation to send.
        if (knownToPce === 'managed' && gs.nil(venHref)) {
            tally.skippedCount++;
            return null;
        }

        return {
            sys_id: workloadGr.getUniqueValue(),
            known_to_pce: knownToPce,
            pce_workload_href: pceHref,
            ven_href: venHref
        };
    },

    buildDeletionPayloadFromSysIds: function(sysIds) {
        var result = {
            success: false,
            message: '',
            retiredWorkloads: {},
            vensToUnpair: [],
            deletionCount: 0,
            unpairCount: 0,
            skippedCount: 0
        };

        try {
            if (!sysIds || sysIds.length === 0) {
                result.message = 'No workload sys_ids provided.';
                return result;
            }

            var chunks = this._chunkArray(sysIds, BATCH_SIZE_MEDIUM);
            for (var c = 0; c < chunks.length; c++) {
                var gr = new GlideRecordSecure(TABLE_PCE_WORKLOAD);
                gr.addQuery('sys_id', 'IN', chunks[c].join(','));
                gr.query();

                while (gr.next()) {
                    var knownToPce = gr.getValue('known_to_pce');
                    var pceHref = gr.getValue('pce_workload_href');

                    if (knownToPce !== 'managed' && knownToPce !== 'unmanaged') {
                        result.skippedCount++;
                        continue;
                    }

                    if (gs.nil(pceHref)) {
                        result.skippedCount++;
                        continue;
                    }

                    if (knownToPce === 'managed') {
                        var venHref = gr.getValue('ven_href');
                        if (!gs.nil(venHref)) {
                            result.vensToUnpair.push(venHref);
                            result.unpairCount++;
                        } else {
                            result.skippedCount++;
                        }
                    } else {
                        if (!result.retiredWorkloads.hasOwnProperty(pceHref)) {
                            // A placeholder, for the reason given in prepareDeletionPayload's
                            // appendRow: this is a set of hrefs, and the sys_id that used to sit
                            // here was read by nothing.
                            result.retiredWorkloads[pceHref] = 1;
                            result.deletionCount++;
                        }
                    }
                }
            }

            result.success = true;
            result.message = result.deletionCount + ' workload(s) for deletion, ' + result.unpairCount + ' workload(s) for unpair' +
                (result.skippedCount > 0 ? ', ' + result.skippedCount + ' skipped' : '');
            this.logger.info('[buildDeletionPayloadFromSysIds] ' + result.message);
        } catch (ex) {
            this.logger.error('[buildDeletionPayloadFromSysIds] Exception: ' + ex);
            result.message = 'Exception occurred: ' + ex;
        }

        return result;
    },

    /**
     * Write a manual deletion's payload to the deletion payload table, in MID-sized rows.
     *
     * The manual path (Delete Workload / Delete Selected Workloads, via IllumioDeletionHandler)
     * used to inline the whole payload into the ECC message and the MID Server read it back from
     * `glide.jms.workloads_to_delete`. R33 moved the filter-driven deletion off the message and
     * onto this table; the MID's delete branch now reads payload rows and nothing else, so the
     * manual path has to write them too or the MID finds nothing to do.
     *
     * Rows are cut at PAYLOAD_ROW_SIZE the same way prepareDeletionPayload cuts them, so both
     * paths produce rows of the same size and the MID's "Batch n/X" means the same thing on each.
     * VENs and workloads are packed independently -- they are counted against separate PCE calls
     * on the MID -- which is why the row cut is checked after each push rather than once.
     *
     * @param {String} jobSysId sys_id of the scheduled job the rows belong to
     * @param {Object} retiredWorkloads { pceHref: 1 } from buildDeletionPayloadFromSysIds
     * @param {Array} vensToUnpair VEN hrefs from buildDeletionPayloadFromSysIds
     * @returns {Number} Rows written, or -1 if any insert failed
     */
    writeDeletionPayloadRows: function(jobSysId, retiredWorkloads, vensToUnpair) {
        var syncUtils = new IllumioSyncUtils();
        var repo = new IllumioSyncRepoUtils(syncUtils);
        // Captured: flush() below is a plain function expression, so `this` is not this object
        // inside it. W3.
        var logger = this.logger.setContext(jobSysId);

        // Same sweep the other two paths do, for the same reason: rows from a run that died are
        // unreachable, because every consumer queries by job.
        repo.deleteStalePayloadRows(syncUtils.DELETION_PAYLOAD_TABLE, jobSysId);

        var extraFields = {};
        extraFields[syncUtils.PAYLOAD_JOB_FIELD] = jobSysId;

        var bundle = { retiredWorkloads: {}, vensToUnpair: [], isDeletion: true };
        var bundleCount = 0;
        var rowCount = 0;
        var failed = false;

        var flush = function() {
            if (bundleCount === 0 || failed) {
                return;
            }

            var rowSysId = repo.insertPayloadRow(
                syncUtils.DELETION_PAYLOAD_TABLE, JSON.stringify(bundle), extraFields);

            if (gs.nil(rowSysId)) {
                logger.error('[writeDeletionPayloadRows] Could not insert a deletion payload row for ' +
                    'job ' + jobSysId + '. Nothing will be sent to the PCE.');
                failed = true;
                return;
            }

            rowCount++;
            bundle = { retiredWorkloads: {}, vensToUnpair: [], isDeletion: true };
            bundleCount = 0;
        };

        var vens = vensToUnpair || [];
        for (var v = 0; v < vens.length && !failed; v++) {
            bundle.vensToUnpair.push(vens[v]);
            bundleCount++;
            if (bundleCount >= syncUtils.PAYLOAD_ROW_SIZE) {
                flush();
            }
        }

        for (var href in retiredWorkloads) {
            if (!retiredWorkloads.hasOwnProperty(href) || failed) {
                continue;
            }
            bundle.retiredWorkloads[href] = 1;
            bundleCount++;
            if (bundleCount >= syncUtils.PAYLOAD_ROW_SIZE) {
                flush();
            }
        }

        flush();

        if (failed) {
            // Withdraw rather than send part of a deletion. A half-written payload deletes a
            // subset the user never chose, and the counts reported back would describe the whole.
            repo.deletePayloadRowsForJob(syncUtils.DELETION_PAYLOAD_TABLE, jobSysId);
            return -1;
        }

        return rowCount;
    },

    type: "IllumioUtils",
};
